    ///                               this (and higher) to define custom success
    ///                               codes.
    /// </summary>
    CustomSuccess = 100,

    /// <summary>Data passing was ok.</summary>
    Ok = 0,

    /// <summary>Pad is not linked.</summary>
    NotLinked = -1,

    /// <summary>Pad is flushing.</summary>
    Flushing = -2,

    /// <summary>Pad is EOS.</summary>
    Eos = -3,

    /// <summary>Pad is not negotiated.</summary>
    NotNegotiated = -4,

    /// <summary>
    /// Some (fatal) error occurred. Element generating
    ///                               this error should post an error message using
    ///                               GST_ELEMENT_ERROR() with more details.
    /// </summary>
    Error = -5,

    /// <summary>This operation is not supported.</summary>
    NotSupported = -6,

    /// <summary>
    /// Elements can use values starting from
    ///                               this (and lower) to define custom error codes.
    /// </summary>
    CustomError = -100,

    /// <summary>
    /// Pre-defined custom error code (define your
    ///                               custom error code to this to avoid compiler
    ///                               warnings).
    /// </summary>
    CustomError1 = -101,

    /// <summary>Pre-defined custom error code.</summary>
    CustomError2 = -102,
}

