}

/// <summary>Flags to control the behavior of a #GstLogContext.</summary>
/// <remarks>
/// <para>Available since GStreamer 1.28.</para>
/// </remarks>
[Flags]
public enum LogContextFlags
{
    /// <summary>No special behavior (empty flags)</summary>
    None = 0x00000000,

    /// <summary>
    /// Enable message throttling/deduplication. This
    ///  makes the context track which messages have been logged already based on
    ///  their message hash, and only log them once (or periodically if an
    ///  interval is set). Without this flag, all messages will be logged regardless
    ///  of whether they've been logged before.
    /// </summary>
    Throttle = 0x00000001,
}

/// <summary>
/// Flags to control how the message hash is calculated in a #GstLogContext.
/// The message hash is used to determine if a message is a duplicate of a previously
/// logged message.
/// </summary>
/// <remarks>
/// <para>Available since GStreamer 1.28.</para>
/// </remarks>
[Flags]
public enum LogContextHashFlags
{
    /// <summary>
    /// Default behavior for logging context
    ///                          (uses object, format, file but not line number or string args)
    /// </summary>
    Default = 0x00000000,

    /// <summary>Ignore object pointer or object ID when calculating message hash</summary>
    IgnoreObject = 0x00000001,

    /// <summary>
    /// Ignore the "format" part of the debug
    /// log message
    /// </summary>
    IgnoreFormat = 0x00000002,

    /// <summary>Ignore file name when calculating message hash</summary>
    IgnoreFile = 0x00000004,

    /// <summary>Use line number when calculating message hash (not used by default)</summary>
    UseLineNumber = 0x00000008,

    /// <summary>Use the arguments part of the string message (not used by default)</summary>
    UseStringArgs = 0x00000010,
}

