    /// <summary>first flag that can be used for custom purposes</summary>
    Last = 0x00100000,
}

/// <summary>The different message types that are available.</summary>
[Flags]
public enum MessageType : uint
{
    /// <summary>an undefined message</summary>
    Unknown = 0x00000000,

    /// <summary>
    /// end-of-stream reached in a pipeline. The application will
    /// only receive this message in the PLAYING state and every time it sets a
    /// pipeline to PLAYING that is in the EOS state. The application can perform a
    /// flushing seek in the pipeline, which will undo the EOS state again.
    /// </summary>
    Eos = 0x00000001,

    /// <summary>
    /// an error occurred. When the application receives an error
    /// message it should stop playback of the pipeline and not assume that more
    /// data will be played. It is possible to specify a redirection url to the error
    /// messages by setting a `redirect-location` field into the error message, application
    /// or high level bins might use the information as required.
    /// </summary>
    Error = 0x00000002,

    /// <summary>a warning occurred.</summary>
    Warning = 0x00000004,

    /// <summary>an info message occurred</summary>
    Info = 0x00000008,

    /// <summary>a tag was found.</summary>
    Tag = 0x00000010,

    /// <summary>
    /// the pipeline is buffering. When the application
    /// receives a buffering message in the PLAYING state for a non-live pipeline it
    /// must PAUSE the pipeline until the buffering completes, when the percentage
    /// field in the message is 100%. For live pipelines, no action must be
    /// performed and the buffering percentage can be used to inform the user about
    /// the progress.
    /// </summary>
    Buffering = 0x00000020,

    /// <summary>a state change happened</summary>
    StateChanged = 0x00000040,

    /// <summary>
    /// an element changed state in a streaming thread.
    /// This message is deprecated.
    /// </summary>
    StateDirty = 0x00000080,

    /// <summary>a stepping operation finished.</summary>
    StepDone = 0x00000100,

    /// <summary>
    /// an element notifies its capability of providing
    ///                             a clock. This message is used internally and
    ///                             never forwarded to the application.
    /// </summary>
    ClockProvide = 0x00000200,

    /// <summary>
    /// The current clock as selected by the pipeline became
    ///                          unusable. The pipeline will select a new clock on
    ///                          the next PLAYING state change. The application
    ///                          should set the pipeline to PAUSED and back to
    ///                          PLAYING when this message is received.
    /// </summary>
    ClockLost = 0x00000400,

    /// <summary>a new clock was selected in the pipeline.</summary>
    NewClock = 0x00000800,

    /// <summary>
    /// the structure of the pipeline changed. This
    /// message is used internally and never forwarded to the application.
    /// </summary>
    StructureChange = 0x00001000,

    /// <summary>
    /// status about a stream, emitted when it starts,
    ///                             stops, errors, etc..
    /// </summary>
    StreamStatus = 0x00002000,

    /// <summary>
    /// message posted by the application, possibly
    ///                           via an application-specific element.
    /// </summary>
    Application = 0x00004000,

    /// <summary>
    /// element-specific message, see the specific element's
    ///                       documentation
    /// </summary>
    Element = 0x00008000,

    /// <summary>
    /// pipeline started playback of a segment. This
    /// message is used internally and never forwarded to the application.
    /// </summary>
    SegmentStart = 0x00010000,

    /// <summary>
    /// pipeline completed playback of a segment. This
    /// message is forwarded to the application after all elements that posted
    /// @GST_MESSAGE_SEGMENT_START posted a GST_MESSAGE_SEGMENT_DONE message.
    /// </summary>
    SegmentDone = 0x00020000,

    /// <summary>
    /// The duration of a pipeline changed. The
    /// application can get the new duration with a duration query.
    /// </summary>
    DurationChanged = 0x00040000,

    /// <summary>
    /// Posted by elements when their latency changes. The
    /// application should recalculate and distribute a new latency.
    /// </summary>
    Latency = 0x00080000,

    /// <summary>
    /// Posted by elements when they start an ASYNC
    /// #GstStateChange. This message is not forwarded to the application but is used
    /// internally.
    /// </summary>
    AsyncStart = 0x00100000,

    /// <summary>
    /// Posted by elements when they complete an ASYNC
    /// #GstStateChange. The application will only receive this message from the toplevel
    /// pipeline.
    /// </summary>
    AsyncDone = 0x00200000,

    /// <summary>
    /// Posted by elements when they want the pipeline to
    /// change state. This message is a suggestion to the application which can
    /// decide to perform the state change on (part of) the pipeline.
    /// </summary>
    RequestState = 0x00400000,

    /// <summary>A stepping operation was started.</summary>
    StepStart = 0x00800000,

    /// <summary>
    /// A buffer was dropped or an element changed its processing
    /// strategy for Quality of Service reasons.
    /// </summary>
    Qos = 0x01000000,

    /// <summary>A progress message.</summary>
    Progress = 0x02000000,

    /// <summary>
    /// A new table of contents (TOC) was found or previously found TOC
    /// was updated.
    /// </summary>
    Toc = 0x04000000,

    /// <summary>
    /// Message to request resetting the pipeline's
    ///     running time from the pipeline. This is an internal message which
    ///     applications will likely never receive.
    /// </summary>
    ResetTime = 0x08000000,

    /// <summary>
    /// Message indicating start of a new stream. Useful
    ///     e.g. when using playbin in gapless playback mode, to get notified when
    ///     the next title actually starts playing (which will be some time after
    ///     the URI for the next title has been set).
    /// </summary>
    StreamStart = 0x10000000,

    /// <summary>Message indicating that an element wants a specific context (Since: 1.2)</summary>
    NeedContext = 0x20000000,

    /// <summary>Message indicating that an element created a context (Since: 1.2)</summary>
    HaveContext = 0x40000000,

    /// <summary>
    /// Message is an extended message type (see below).
    ///     These extended message IDs can't be used directly with mask-based API
    ///     like gst_bus_poll() or gst_bus_timed_pop_filtered(), but you can still
    ///     filter for GST_MESSAGE_EXTENDED and then check the result for the
    ///     specific type. (Since: 1.4)
    /// </summary>
    Extended = 0x80000000,

    /// <summary>
    /// Message indicating a #GstDevice was added to
    ///     a #GstDeviceProvider (Since: 1.4)
    /// </summary>
    DeviceAdded = 0x80000001,

    /// <summary>
    /// Message indicating a #GstDevice was removed
    ///     from a #GstDeviceProvider (Since: 1.4)
    /// </summary>
    DeviceRemoved = 0x80000002,

    /// <summary>
    /// Message indicating a #GObject property has
    ///     changed (Since: 1.10)
    /// </summary>
    PropertyNotify = 0x80000003,

    /// <summary>
    /// Message indicating a new #GstStreamCollection
    ///     is available (Since: 1.10)
    /// </summary>
    StreamCollection = 0x80000004,

    /// <summary>
    /// Message indicating the active selection of
    ///     #GstStreams has changed (Since: 1.10)
    /// </summary>
    StreamsSelected = 0x80000005,

    /// <summary>
    /// Message indicating to request the application to
    ///     try to play the given URL(s). Useful if for example a HTTP 302/303
    ///     response is received with a non-HTTP URL inside. (Since: 1.10)
    /// </summary>
    Redirect = 0x80000006,

    /// <summary>
    /// Message indicating a #GstDevice was changed
    ///     a #GstDeviceProvider (Since: 1.16)
    /// </summary>
    DeviceChanged = 0x80000007,

    /// <summary>
    /// Message sent by elements to request the
    ///     running time from the pipeline when an instant rate change should
    ///     be applied (which may be in the past when the answer arrives). (Since: 1.18)
    /// </summary>
    InstantRateRequest = 0x80000008,

    /// <summary>Message indicating the #GstDeviceMonitor has completed async startup.</summary>
    /// <remarks>
    /// <para>Available since GStreamer 1.28.</para>
    /// </remarks>
    DeviceMonitorStarted = 0x80000009,

    /// <summary>mask for all of the above messages.</summary>
    Any = 0xFFFFFFFF,
}

/// <summary>Extra metadata flags.</summary>
[Flags]
public enum MetaFlags
{
    /// <summary>no flags</summary>
    None = 0x00000000,

    /// <summary>metadata should not be modified</summary>
    Readonly = 0x00000001,

    /// <summary>metadata is managed by a bufferpool</summary>
    Pooled = 0x00000002,

    /// <summary>metadata should not be removed</summary>
    Locked = 0x00000004,

    /// <summary>additional flags can be added starting from this flag.</summary>
    Last = 0x00010000,
}

/// <summary>Flags for the mini object</summary>
[Flags]
public enum MiniObjectFlags
{
    /// <summary>
    /// the object can be locked and unlocked with
    /// gst_mini_object_lock() and gst_mini_object_unlock().
    /// </summary>
    Lockable = 0x00000001,

    /// <summary>
    /// the object is permanently locked in
    /// READONLY mode. Only read locks can be performed on the object.
    /// </summary>
    LockReadonly = 0x00000002,

    /// <summary>
    /// the object is expected to stay alive
    /// even after gst_deinit() has been called and so should be ignored by leak
    /// detection tools. (Since: 1.10)
    /// </summary>
    MayBeLeaked = 0x00000004,

    /// <summary>first flag that can be used by subclasses.</summary>
    Last = 0x00000010,
}

/// <summary>The standard flags that an gstobject may have.</summary>
[Flags]
public enum ObjectFlags
{
    /// <summary>
    /// the object is expected to stay alive even
    /// after gst_deinit() has been called and so should be ignored by leak
    /// detection tools. (Since: 1.10)
    /// </summary>
    MayBeLeaked = 0x00000001,

    /// <summary>
    /// Flag that's set when the object has been constructed. This can be used by
    /// API such as base class setters to differentiate between the case where
    /// they're called from a subclass's instance init function (and where the
    /// object isn't fully constructed yet, and so one shouldn't do anything but
    /// set values in the instance structure), and the case where the object is
    /// constructed.
    /// </summary>
    Constructed = 0x00000002,

    /// <summary>subclasses can add additional flags starting from this flag</summary>
    Last = 0x00000010,
}

/// <summary>The direction of a pad.</summary>
public enum PadDirection
{
    /// <summary>direction is unknown.</summary>
    Unknown = 0,

    /// <summary>the pad is a source pad.</summary>
    Src = 1,

    /// <summary>the pad is a sink pad.</summary>
    Sink = 2,
}

/// <summary>Pad state flags</summary>
[Flags]
public enum PadFlags
{
    /// <summary>is dataflow on a pad blocked</summary>
    Blocked = 0x00000010,

    /// <summary>is pad flushing</summary>
    Flushing = 0x00000020,

    /// <summary>is pad in EOS state</summary>
    Eos = 0x00000040,

    /// <summary>is pad currently blocking on a buffer or event</summary>
    Blocking = 0x00000080,

    /// <summary>
    /// ensure that there is a parent object before calling
    ///                       into the pad callbacks.
    /// </summary>
    NeedParent = 0x00000100,

    /// <summary>
    /// the pad should be reconfigured/renegotiated.
    ///                            The flag has to be unset manually after
    ///                            reconfiguration happened.
    /// </summary>
    NeedReconfigure = 0x00000200,

    /// <summary>the pad has pending events</summary>
    PendingEvents = 0x00000400,

    /// <summary>
    /// the pad is using fixed caps. This means that
    ///     once the caps are set on the pad, the default caps query function
    ///     will only return those caps.
    /// </summary>
    FixedCaps = 0x00000800,

    /// <summary>
    /// the default event and query handler will forward
    ///                      all events and queries to the internally linked pads
    ///                      instead of discarding them.
    /// </summary>
    ProxyCaps = 0x00001000,

    /// <summary>
    /// the default query handler will forward
    ///                      allocation queries to the internally linked pads
    ///                      instead of discarding them.
    /// </summary>
    ProxyAllocation = 0x00002000,

    /// <summary>
    /// the default query handler will forward
    ///                      scheduling queries to the internally linked pads
    ///                      instead of discarding them.
    /// </summary>
    ProxyScheduling = 0x00004000,

    /// <summary>
    /// the default accept-caps handler will check
    ///                      it the caps intersect the query-caps result instead
    ///                      of checking for a subset. This is interesting for
    ///                      parsers that can accept incompletely specified caps.
    /// </summary>
    AcceptIntersect = 0x00008000,

    /// <summary>
    /// the default accept-caps handler will use
    ///                      the template pad caps instead of query caps to
    ///                      compare with the accept caps. Use this in combination
    ///                      with %GST_PAD_FLAG_ACCEPT_INTERSECT. (Since: 1.6)
    /// </summary>
    AcceptTemplate = 0x00010000,

    /// <summary>offset to define more flags</summary>
    Last = 0x00100000,
}

/// <summary>
/// The amount of checking to be done when linking pads. @GST_PAD_LINK_CHECK_CAPS
/// and @GST_PAD_LINK_CHECK_TEMPLATE_CAPS are mutually exclusive. If both are
/// specified, expensive but safe @GST_PAD_LINK_CHECK_CAPS are performed.
/// </summary>
/// <remarks>
/// <para>
/// &gt; Only disable some of the checks if you are 100% certain you know the link
/// &gt; will not fail because of hierarchy/caps compatibility failures. If uncertain,
/// &gt; use the default checks (%GST_PAD_LINK_CHECK_DEFAULT) or the regular methods
/// &gt; for linking the pads.
/// </para>
/// </remarks>
[Flags]
public enum PadLinkCheck
{
    /// <summary>Don't check hierarchy or caps compatibility.</summary>
    Nothing = 0x00000000,

    /// <summary>
    /// Check the pads have same parents/grandparents.
    ///   Could be omitted if it is already known that the two elements that own the
    ///   pads are in the same bin.
    /// </summary>
    Hierarchy = 0x00000001,

    /// <summary>
    /// Check if the pads are compatible by using
    ///   their template caps. This is much faster than @GST_PAD_LINK_CHECK_CAPS, but
    ///   would be unsafe e.g. if one pad has %GST_CAPS_ANY.
    /// </summary>
    TemplateCaps = 0x00000002,

    /// <summary>
    /// Check if the pads are compatible by comparing the
    ///   caps returned by gst_pad_query_caps().
    /// </summary>
    Caps = 0x00000004,

    /// <summary>
    /// Disables pushing a reconfigure event when pads are
    ///   linked.
    /// </summary>
    NoReconfigure = 0x00000008,

    /// <summary>
    /// The default checks done when linking
    ///   pads (i.e. the ones used by gst_pad_link()).
    /// </summary>
    Default = 0x00000005,
}

/// <summary>Result values from gst_pad_link and friends.</summary>
public enum PadLinkReturn
{
    /// <summary>link succeeded</summary>
    Ok = 0,

    /// <summary>pads have no common grandparent</summary>
    WrongHierarchy = -1,

    /// <summary>pad was already linked</summary>
    WasLinked = -2,

    /// <summary>pads have wrong direction</summary>
    WrongDirection = -3,

    /// <summary>pads do not have common format</summary>
    Noformat = -4,

    /// <summary>pads cannot cooperate in scheduling</summary>
    Nosched = -5,

    /// <summary>refused for some reason</summary>
    Refused = -6,
}

/// <summary>
/// The status of a GstPad. After activating a pad, which usually happens when the
/// parent element goes from READY to PAUSED, the GstPadMode defines if the
/// pad operates in push or pull mode.
/// </summary>
public enum PadMode
{
    /// <summary>Pad will not handle dataflow</summary>
    None = 0,

    /// <summary>Pad handles dataflow in downstream push mode</summary>
    Push = 1,

    /// <summary>Pad handles dataflow in upstream pull mode</summary>
    Pull = 2,
}

/// <summary>Indicates when this pad will become available.</summary>
public enum PadPresence
{
    /// <summary>the pad is always available</summary>
    Always = 0,

    /// <summary>the pad will become available depending on the media stream</summary>
    Sometimes = 1,

    /// <summary>
    /// the pad is only available on request with
    ///  gst_element_request_pad().
    /// </summary>
    Request = 2,
}

/// <summary>Different return values for the #GstPadProbeCallback.</summary>
public enum PadProbeReturn
{
    /// <summary>
    /// drop data in data probes. For push mode this means that
    ///        the data item is not sent downstream. For pull mode, it means that
    ///        the data item is not passed upstream. In both cases, no other probes
    ///        are called for this item and %GST_FLOW_OK or %TRUE is returned to the
    ///        caller.
    /// </summary>
    Drop = 0,

    /// <summary>
    /// normal probe return value. This leaves the probe in
    ///        place, and defers decisions about dropping or passing data to other
    ///        probes, if any. If there are no other probes, the default behaviour
    ///        for the probe type applies ('block' for blocking probes,
    ///        and 'pass' for non-blocking probes).
    /// </summary>
    Ok = 1,

    /// <summary>
    /// remove this probe, passing the data. For blocking probes
    ///        this will cause data flow to unblock, unless there are also other
    ///        blocking probes installed.
    /// </summary>
    Remove = 2,

    /// <summary>
    /// pass the data item in the block probe and block on the
    ///        next item. Note, that if there are multiple pad probes installed and
    ///        any probe returns PASS, the data will be passed.
    /// </summary>
    Pass = 3,

    /// <summary>
    /// Data has been handled in the probe and will not be
    ///        forwarded further. For events and buffers this is the same behaviour as
    ///        %GST_PAD_PROBE_DROP (except that in this case you need to unref the buffer
    ///        or event yourself). For queries it will also return %TRUE to the caller.
    ///        The probe can also modify the #GstFlowReturn value by using the
    ///        #GST_PAD_PROBE_INFO_FLOW_RETURN() accessor.
    ///        Note that the resulting query must contain valid entries.
    ///        Since: 1.6
    /// </summary>
    Handled = 4,
}

/// <summary>
/// The different probing types that can occur. When either one of
/// @GST_PAD_PROBE_TYPE_IDLE or @GST_PAD_PROBE_TYPE_BLOCK is used, the probe will be a
/// blocking probe.
/// </summary>
[Flags]
public enum PadProbeType
{
    /// <summary>invalid probe type</summary>
    Invalid = 0x00000000,

    /// <summary>probe idle pads and block while the callback is called</summary>
    Idle = 0x00000001,

    /// <summary>probe and block pads</summary>
    Block = 0x00000002,

    /// <summary>probe buffers</summary>
    Buffer = 0x00000010,

    /// <summary>probe buffer lists</summary>
    BufferList = 0x00000020,

    /// <summary>probe downstream events</summary>
    EventDownstream = 0x00000040,

    /// <summary>probe upstream events</summary>
    EventUpstream = 0x00000080,

    /// <summary>
    /// probe flush events. This probe has to be
    ///     explicitly enabled and is not included in the
    ///     @@GST_PAD_PROBE_TYPE_EVENT_DOWNSTREAM or
    ///     @@GST_PAD_PROBE_TYPE_EVENT_UPSTREAM probe types.
    /// </summary>
    EventFlush = 0x00000100,

    /// <summary>probe downstream queries</summary>
    QueryDownstream = 0x00000200,

    /// <summary>probe upstream queries</summary>
    QueryUpstream = 0x00000400,

    /// <summary>probe push</summary>
    Push = 0x00001000,

    /// <summary>probe pull</summary>
    Pull = 0x00002000,

    /// <summary>probe and block at the next opportunity, at data flow or when idle</summary>
    Blocking = 0x00000003,

    /// <summary>probe downstream data (buffers, buffer lists, and events)</summary>
    DataDownstream = 0x00000070,

    /// <summary>probe upstream data (events)</summary>
    DataUpstream = 0x00000080,

    /// <summary>probe upstream and downstream data (buffers, buffer lists, and events)</summary>
    DataBoth = 0x000000F0,

    /// <summary>probe and block downstream data (buffers, buffer lists, and events)</summary>
    BlockDownstream = 0x00000072,

    /// <summary>probe and block upstream data (events)</summary>
    BlockUpstream = 0x00000082,

    /// <summary>probe upstream and downstream events</summary>
    EventBoth = 0x000000C0,

    /// <summary>probe upstream and downstream queries</summary>
    QueryBoth = 0x00000600,

    /// <summary>
    /// probe upstream events and queries and downstream buffers, buffer lists, events and queries
    /// </summary>
    AllBoth = 0x000006F0,

    /// <summary>probe push and pull</summary>
    Scheduling = 0x00003000,
}

