/// <summary>
/// The possible states an element can be in. States can be changed using
/// gst_element_set_state() and checked using gst_element_get_state().
/// </summary>
public enum State
{
    /// <summary>no pending state.</summary>
    VoidPending = 0,

    /// <summary>the NULL state or initial state of an element.</summary>
    Null = 1,

    /// <summary>the element is ready to go to PAUSED.</summary>
    Ready = 2,

    /// <summary>
    /// the element is PAUSED, it is ready to accept and
    ///                          process data. Sink elements however only accept one
    ///                          buffer and then block.
    /// </summary>
    Paused = 3,

    /// <summary>
    /// the element is PLAYING, the #GstClock is running and
    ///                          the data is flowing.
    /// </summary>
    Playing = 4,
}

/// <summary>
/// These are the different state changes an element goes through.
/// %GST_STATE_NULL &amp;rArr; %GST_STATE_PLAYING is called an upwards state change
/// and %GST_STATE_PLAYING &amp;rArr; %GST_STATE_NULL a downwards state change.
/// </summary>
public enum StateChange
{
    /// <summary>
    /// state change from NULL to READY.
    ///   * The element must check if the resources it needs are available. Device
    ///     sinks and -sources typically try to probe the device to constrain their
    ///     caps.
    ///   * The element opens the device (in case feature need to be probed).
    /// </summary>
    NullToReady = 10,

    /// <summary>
    /// state change from READY to PAUSED.
    ///   * The element pads are activated in order to receive data in PAUSED.
    ///     Streaming threads are started.
    ///   * Some elements might need to return %GST_STATE_CHANGE_ASYNC and complete
    ///     the state change when they have enough information. It is a requirement
    ///     for sinks to return %GST_STATE_CHANGE_ASYNC and complete the state change
    ///     when they receive the first buffer or %GST_EVENT_EOS (preroll).
    ///     Sinks also block the dataflow when in PAUSED.
    ///   * A pipeline resets the running_time to 0.
    ///   * Live sources return %GST_STATE_CHANGE_NO_PREROLL and don't generate data.
    /// </summary>
    ReadyToPaused = 19,

    /// <summary>
    /// state change from PAUSED to PLAYING.
    ///   * Most elements ignore this state change.
    ///   * The pipeline selects a #GstClock and distributes this to all the children
    ///     before setting them to PLAYING. This means that it is only allowed to
    ///     synchronize on the #GstClock in the PLAYING state.
    ///   * The pipeline uses the #GstClock and the running_time to calculate the
    ///     base_time. The base_time is distributed to all children when performing
    ///     the state change.
    ///   * Sink elements stop blocking on the preroll buffer or event and start
    ///     rendering the data.
    ///   * Sinks can post %GST_MESSAGE_EOS in the PLAYING state. It is not allowed
    ///     to post %GST_MESSAGE_EOS when not in the PLAYING state.
    ///   * While streaming in PAUSED or PLAYING elements can create and remove
    ///     sometimes pads.
    ///   * Live sources start generating data and return %GST_STATE_CHANGE_SUCCESS.
    /// </summary>
    PausedToPlaying = 28,

    /// <summary>
    /// state change from PLAYING to PAUSED.
    ///   * Most elements ignore this state change.
    ///   * The pipeline calculates the running_time based on the last selected
    ///     #GstClock and the base_time. It stores this information to continue
    ///     playback when going back to the PLAYING state.
    ///   * Sinks unblock any #GstClock wait calls.
    ///   * When a sink does not have a pending buffer to play, it returns
    ///     #GST_STATE_CHANGE_ASYNC from this state change and completes the state
    ///     change when it receives a new buffer or an %GST_EVENT_EOS.
    ///   * Any queued %GST_MESSAGE_EOS items are removed since they will be reposted
    ///     when going back to the PLAYING state. The EOS messages are queued in
    ///     #GstBin containers.
    ///   * Live sources stop generating data and return %GST_STATE_CHANGE_NO_PREROLL.
    /// </summary>
    PlayingToPaused = 35,

    /// <summary>
    /// state change from PAUSED to READY.
    ///   * Sinks unblock any waits in the preroll.
    ///   * Elements unblock any waits on devices
    ///   * Chain or get_range functions return %GST_FLOW_FLUSHING.
    ///   * The element pads are deactivated so that streaming becomes impossible and
    ///     all streaming threads are stopped.
    ///   * The sink forgets all negotiated formats
    ///   * Elements remove all sometimes pads
    /// </summary>
    PausedToReady = 26,

    /// <summary>
    /// state change from READY to NULL.
    ///   * Elements close devices
    ///   * Elements reset any internal state.
    /// </summary>
    ReadyToNull = 17,

    /// <summary>state change from NULL to NULL. (Since: 1.14)</summary>
    NullToNull = 9,

    /// <summary>
    /// state change from READY to READY,
    /// This might happen when going to PAUSED asynchronously failed, in that case
    /// elements should make sure they are in a proper, coherent READY state. (Since: 1.14)
    /// </summary>
    ReadyToReady = 18,

    /// <summary>
    /// state change from PAUSED to PAUSED.
    /// This might happen when elements were in PLAYING state and 'lost state',
    /// they should make sure to go back to real 'PAUSED' state (prerolling for example). (Since: 1.14)
    /// </summary>
    PausedToPaused = 27,

    /// <summary>state change from PLAYING to PLAYING. (Since: 1.14)</summary>
    PlayingToPlaying = 36,
}

/// <summary>
/// The possible return values from a state change function such as
/// gst_element_set_state(). Only @GST_STATE_CHANGE_FAILURE is a real failure.
/// </summary>
public enum StateChangeReturn
{
    /// <summary>the state change failed</summary>
    Failure = 0,

    /// <summary>the state change succeeded</summary>
    Success = 1,

    /// <summary>the state change will happen asynchronously</summary>
    Async = 2,

    /// <summary>
    /// the state change succeeded but the element
    ///                               cannot produce data in %GST_STATE_PAUSED.
    ///                               This typically happens with live sources.
    /// </summary>
    NoPreroll = 3,
}

/// <summary>
/// Stream errors are for anything related to the stream being processed:
/// format errors, media type errors, ...
/// They're typically used by decoders, demuxers, converters, ...
/// </summary>
public enum StreamError
{
    /// <summary>
    /// a general error which doesn't fit in any other
    /// category.  Make sure you add a custom message to the error call.
    /// </summary>
    Failed = 1,

    /// <summary>
    /// do not use this except as a placeholder for
    /// deciding where to go while developing code.
    /// </summary>
    TooLazy = 2,

    /// <summary>
    /// use this when you do not want to implement
    /// this functionality yet.
    /// </summary>
    NotImplemented = 3,

    /// <summary>
    /// used when the element doesn't know the
    /// stream's type.
    /// </summary>
    TypeNotFound = 4,

    /// <summary>
    /// used when the element doesn't handle this type
    /// of stream.
    /// </summary>
    WrongType = 5,

    /// <summary>
    /// used when there's no codec to handle the
    /// stream's type.
    /// </summary>
    CodecNotFound = 6,

    /// <summary>used when decoding fails.</summary>
    Decode = 7,

    /// <summary>used when encoding fails.</summary>
    Encode = 8,

    /// <summary>used when demuxing fails.</summary>
    Demux = 9,

    /// <summary>used when muxing fails.</summary>
    Mux = 10,

    /// <summary>
    /// used when the stream is of the wrong format
    /// (for example, wrong caps).
    /// </summary>
    Format = 11,

    /// <summary>
    /// used when the stream is encrypted and can't be
    /// decrypted because this is not supported by the element.
    /// </summary>
    Decrypt = 12,

    /// <summary>
    /// used when the stream is encrypted and
    /// can't be decrypted because no suitable key is available.
    /// </summary>
    DecryptNokey = 13,

    /// <summary>the number of stream error types.</summary>
    NumErrors = 14,
}

/// <summary>The <c>GstStreamFlags</c> flags.</summary>
[Flags]
public enum StreamFlags
{
    /// <summary>This stream has no special attributes</summary>
    None = 0x00000000,

    /// <summary>
    /// This stream is a sparse stream (e.g. a subtitle
    ///    stream), data may flow only in irregular intervals with large gaps in
    ///    between.
    /// </summary>
    Sparse = 0x00000001,

    /// <summary>
    /// This stream should be selected by default. This
    ///    flag may be used by demuxers to signal that a stream should be selected
    ///    by default in a playback scenario.
    /// </summary>
    Select = 0x00000002,

    /// <summary>
    /// This stream should not be selected by default.
    ///    This flag may be used by demuxers to signal that a stream should not
    ///    be selected by default in a playback scenario, but only if explicitly
    ///    selected by the user (e.g. an audio track for the hard of hearing or
    ///    a director's commentary track).
    /// </summary>
    Unselect = 0x00000004,
}

/// <summary>
/// The type of a %GST_MESSAGE_STREAM_STATUS. The stream status messages inform the
/// application of new streaming threads and their status.
/// </summary>
public enum StreamStatusType
{
    /// <summary>A new thread need to be created.</summary>
    Create = 0,

    /// <summary>a thread entered its loop function</summary>
    Enter = 1,

    /// <summary>a thread left its loop function</summary>
    Leave = 2,

    /// <summary>a thread is destroyed</summary>
    Destroy = 3,

    /// <summary>a thread is started</summary>
    Start = 8,

    /// <summary>a thread is paused</summary>
    Pause = 9,

    /// <summary>a thread is stopped</summary>
    Stop = 10,
}

/// <summary>
/// #GstStreamType describes a high level classification set for
/// flows of data in #GstStream objects.
/// </summary>
/// <remarks>
/// <para>
/// Note that this is a flag, and therefore users should not assume it
/// will be a single value. Do not use the equality operator for checking
/// whether a stream is of a certain type.
/// </para>
/// </remarks>
[Flags]
public enum StreamType
{
    /// <summary>The stream is of unknown (unclassified) type.</summary>
    Unknown = 0x00000001,

    /// <summary>The stream is of audio data</summary>
    Audio = 0x00000002,

    /// <summary>The stream carries video data</summary>
    Video = 0x00000004,

    /// <summary>The stream is a muxed container type</summary>
    Container = 0x00000008,

    /// <summary>The stream contains subtitle / subpicture data.</summary>
    Text = 0x00000010,

    /// <summary>The stream contains metadata.</summary>
    /// <remarks>
    /// <para>Available since GStreamer 1.28.</para>
    /// </remarks>
    Metadata = 0x00000020,
}

/// <summary>The type of a %GST_MESSAGE_STRUCTURE_CHANGE.</summary>
public enum StructureChangeType
{
    /// <summary>Pad linking is starting or done.</summary>
    Link = 0,

    /// <summary>Pad unlinking is starting or done.</summary>
    Unlink = 1,
}

/// <summary>Extra tag flags used when registering tags.</summary>
public enum TagFlag
{
    /// <summary>undefined flag</summary>
    Undefined = 0,

    /// <summary>tag is meta data</summary>
    Meta = 1,

    /// <summary>tag is encoded</summary>
    Encoded = 2,

    /// <summary>tag is decoded</summary>
    Decoded = 3,

    /// <summary>number of tag flags</summary>
    Count = 4,
}

/// <summary>
/// The different tag merging modes are basically replace, overwrite and append,
/// but they can be seen from two directions. Given two taglists: (A) the tags
/// already in the element and (B) the ones that are supplied to the element (
/// e.g. via gst_tag_setter_merge_tags() / gst_tag_setter_add_tags() or a
/// %GST_EVENT_TAG), how are these tags merged?
/// In the table below this is shown for the cases that a tag exists in the list
/// (A) or does not exists (!A) and combinations thereof.
/// </summary>
/// <remarks>
/// <para>
/// | merge mode  | A + B | A + !B | !A + B | !A + !B |
/// | ----------- | ----- | ------ | ------ | ------- |
/// | REPLACE_ALL | B     | ø      | B      | ø       |
/// | REPLACE     | B     | A      | B      | ø       |
/// | APPEND      | A, B  | A      | B      | ø       |
/// | PREPEND     | B, A  | A      | B      | ø       |
/// | KEEP        | A     | A      | B      | ø       |
/// | KEEP_ALL    | A     | A      | ø      | ø       |
/// </para>
/// </remarks>
public enum TagMergeMode
{
    /// <summary>undefined merge mode</summary>
    Undefined = 0,

    /// <summary>replace all tags (clear list and append)</summary>
    ReplaceAll = 1,

    /// <summary>replace tags</summary>
    Replace = 2,

    /// <summary>append tags</summary>
    Append = 3,

    /// <summary>prepend tags</summary>
    Prepend = 4,

    /// <summary>keep existing tags</summary>
    Keep = 5,

    /// <summary>keep all existing tags</summary>
    KeepAll = 6,

    /// <summary>the number of merge modes</summary>
    Count = 7,
}

/// <summary>
/// GstTagScope specifies if a taglist applies to the complete
/// medium or only to one single stream.
/// </summary>
public enum TagScope
{
    /// <summary>tags specific to this single stream</summary>
    Stream = 0,

    /// <summary>global tags for the complete medium</summary>
    Global = 1,
}

/// <summary>The different states a task can be in</summary>
public enum TaskState
{
    /// <summary>the task is started and running</summary>
    Started = 0,

    /// <summary>the task is stopped</summary>
    Stopped = 1,

    /// <summary>the task is paused</summary>
    Paused = 2,
}

/// <summary>The different types of TOC entries (see #GstTocEntry).</summary>
/// <remarks>
/// <para>There are two types of TOC entries: alternatives or parts in a sequence.</para>
/// </remarks>
public enum TocEntryType
{
    /// <summary>entry is an angle (i.e. an alternative)</summary>
    Angle = -3,

    /// <summary>entry is a version (i.e. alternative)</summary>
    Version = -2,

    /// <summary>entry is an edition (i.e. alternative)</summary>
    Edition = -1,

    /// <summary>invalid entry type value</summary>
    Invalid = 0,

    /// <summary>entry is a title (i.e. a part of a sequence)</summary>
    Title = 1,

    /// <summary>entry is a track (i.e. a part of a sequence)</summary>
    Track = 2,

    /// <summary>entry is a chapter (i.e. a part of a sequence)</summary>
    Chapter = 3,
}

/// <summary>
/// How a #GstTocEntry should be repeated. By default, entries are played a
/// single time.
/// </summary>
public enum TocLoopType
{
    /// <summary>single forward playback</summary>
    None = 0,

    /// <summary>repeat forward</summary>
    Forward = 1,

    /// <summary>repeat backward</summary>
    Reverse = 2,

    /// <summary>repeat forward and backward</summary>
    PingPong = 3,
}

/// <summary>The scope of a TOC.</summary>
public enum TocScope
{
    /// <summary>
    /// global TOC representing all selectable options
    ///     (this is what applications are usually interested in)
    /// </summary>
    Global = 1,

    /// <summary>
    /// TOC for the currently active/selected stream
    ///     (this is a TOC representing the current stream from start to EOS,
    ///     and is what a TOC writer / muxer is usually interested in; it will
    ///     usually be a subset of the global TOC, e.g. just the chapters of
    ///     the current title, or the chapters selected for playback from the
    ///     current title)
    /// </summary>
    Current = 2,
}

/// <summary>
/// Flag that describe the value. These flags help applications processing the
/// logs to understand the values.
/// </summary>
[Flags]
public enum TracerValueFlags
{
    /// <summary>no flags</summary>
    None = 0x00000000,

    /// <summary>
    /// the value is optional. When using this flag
    ///   one need to have an additional boolean arg before this value in the
    ///   var-args list passed to  gst_tracer_record_log().
    /// </summary>
    Optional = 0x00000001,

    /// <summary>
    /// the value is a combined figure, since the
    ///   start of tracing. Examples are averages or timestamps.
    /// </summary>
    Aggregated = 0x00000002,
}

/// <summary>
/// Tracing record will contain fields that contain a measured value or extra
/// meta-data. One such meta data are values that tell where a measurement was
/// taken. This enumerating declares to which scope such a meta data field
/// relates to. If it is e.g. %GST_TRACER_VALUE_SCOPE_PAD, then each of the log
/// events may contain values for different #GstPads.
/// </summary>
public enum TracerValueScope
{
    /// <summary>the value is related to the process</summary>
    Process = 0,

    /// <summary>the value is related to a thread</summary>
    Thread = 1,

    /// <summary>the value is related to an #GstElement</summary>
    Element = 2,

    /// <summary>the value is related to a #GstPad</summary>
    Pad = 3,
}

/// <summary>
/// The probability of the typefind function. Higher values have more certainty
/// in doing a reliable typefind.
/// </summary>
public enum TypeFindProbability
{
    /// <summary>type undetected.</summary>
    None = 0,

    /// <summary>unlikely typefind.</summary>
    Minimum = 1,

    /// <summary>possible type detected.</summary>
    Possible = 50,

    /// <summary>likely a type was detected.</summary>
    Likely = 80,

    /// <summary>nearly certain that a type was detected.</summary>
    NearlyCertain = 99,

    /// <summary>very certain a type was detected.</summary>
    Maximum = 100,
}

/// <summary>Different URI-related errors that can occur.</summary>
public enum URIError
{
    /// <summary>The protocol is not supported</summary>
    UnsupportedProtocol = 0,

    /// <summary>There was a problem with the URI</summary>
    BadUri = 1,

    /// <summary>
    /// Could not set or change the URI because the
    ///     URI handler was in a state where that is not possible or not permitted
    /// </summary>
    BadState = 2,

    /// <summary>
    /// There was a problem with the entity that
    ///     the URI references
    /// </summary>
    BadReference = 3,
}

/// <summary>The different types of URI direction.</summary>
public enum URIType
{
    /// <summary>The URI direction is unknown</summary>
    Unknown = 0,

    /// <summary>The URI is a consumer.</summary>
    Sink = 1,

    /// <summary>The URI is a producer.</summary>
    Src = 2,
}
